#!/bin/bash
set -eu
export PYTHONDONTWRITEBYTECODE=1
exec /home/loosqk/.local/share/uv/python/cpython-3.12.13-linux-aarch64-gnu/bin/python3 - <<'PYREMOTE'
import base64,hashlib,json,os,subprocess,tarfile,time
from pathlib import Path
base=Path('/home/loosqk/robot-checks/position-return-20261010-r1');phase=base/'head2-p32-trial-r14';boot=base/'head2-p32-trial-r14-prepare-boot'
assert not phase.exists() and not boot.exists()
boot.mkdir(mode=0o700)
payload = {'prepare_r14.py': {'base64': '', 'sha256': '6be9f5c9132374954c5c6e485e50136171917c9fb848b2aec683bc321b81a626', 'bytes': 289118}, 'launch_prepare_r14.sh': {'base64': '', 'sha256': '28a3be86ef75d1a8db9e732cfc5e2d3aae2a5bc13baf3c18bcb96dd402e818a0', 'bytes': 394}}

for name,row in payload.items():
 raw=base64.b64decode(row['base64'],validate=True);assert len(raw)==row['bytes'] and hashlib.sha256(raw).hexdigest()==row['sha256']
 with (boot/name).open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
rows=[]
def command(name,argv,allowed):
 started=time.time_ns();child=subprocess.Popen(argv,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE);stdout,stderr=child.communicate();code=child.wait()
 row={'name':name,'argv':argv,'pid':child.pid,'started_ns':started,'finished_ns':time.time_ns(),'exit_code':code,'wait_returncode':code,'reaped':True,'stdout':stdout.decode(),'stderr':stderr.decode(),'signals_sent':[]};rows.append(row)
 with (boot/(name+'.receipt.json')).open('x') as f:json.dump(row,f,ensure_ascii=False,indent=2);f.write('\n')
 assert code in allowed,row
 return code,stdout,stderr
_,raw,stderr=command('single-tmux-software-prepare',['tmux','new-session','-d','-s','position-head2-p32-prepare-20261011-r14','-P','-F','#{session_name} #{window_id} #{pane_id} #{pane_pid}','bash '+str(boot/'launch_prepare_r14.sh')],(0,))
assert not stderr
session,window,pane,pid=raw.decode().split();assert session=='position-head2-p32-prepare-20261011-r14' and pid.isdigit()
print(json.dumps({'phase':'ACTUAL_SINGLE_HEAD2_P32_SOFTWARE_PREPARE_START','runtime_pid':int(pid),'pane':pane,'tmux_launch':rows[-1]},ensure_ascii=False),flush=True)
observer='#!/bin/bash\n# 本轮软件质量观察副本；无UART/GO/服务动作。\n# SSH 等待同一 pane 的退出通知，通知后仍只读核验真实终态。\nset -euC\numask 077\nexport PATH=/home/loosqk/.cargo/bin:/home/loosqk/.local/bin:$PATH\nbase=/home/loosqk/robot-checks/position-return-20261010-r1\nrecord="/home/loosqk/robot-checks/position-return-20261010-r1/head2-p32-trial-r14-prepare-boot/observer-event"\nmkdir "$record"\nprintf \'%s\\n\' \'__ACTUAL_PANE_LINE__\' > "$record/pane.txt"\nread -r pane driver_pid window < "$record/pane.txt"\ncase "$pane" in %[0-9]*) ;; *) exit 2;; esac\ncase "$driver_pid" in \'\'|*[!0-9]*) exit 2;; esac\n# 同一服务器的 pane_id 不复用；同一记录目录的 observer PID 文件不覆盖。\n# 每个观察者有自己的 indexed hook/channel，续接不覆盖旧 waiter。\nobserver=$$\nchannel="quality.pane.${pane#%}.driver.$driver_pid.observer.$observer"\nhook="pane-died[$observer]"\nprintf \'%s\\n\' "$channel" > "$record/observer-$observer.channel"\nbefore_hooks=$(tmux show-hooks -p -t "$pane")\nprintf \'%s\\n\' "$before_hooks" > "$record/observer-$observer.hooks-before"\nwhile read -r hook_name hook_command; do\n  if [ "$hook_name" = "$hook" ]; then exit 2; fi\ndone <<< "$before_hooks"\ncleanup_hook() {\n  tmux set-hook -pu -t "$pane" "$hook"\n}\ntrap cleanup_hook EXIT\ntmux set-hook -p -t "$pane" "$hook" "wait-for -S $channel"\ntmux show-hooks -p -t "$pane" > "$record/observer-$observer.hooks-after"\nobserve() {\n  state=$(tmux display-message -p -t "$pane" \'#{pane_id} #{pane_pid} #{pane_dead} #{pane_dead_status}\')\n  printf \'%s\\n\' "$state" >> "$record/observer-$observer.log"\n  read -r observed_pane observed_pid dead status <<< "$state"\n  test "$observed_pane" = "$pane"\n  test "$observed_pid" = "$driver_pid"\n}\n# 挂钩后查询：先退出的 pane 直接核验；查询到存活后的退出由 channel 留存通知。\nobserve\nif [ "$dead" = 0 ]; then\n  tmux wait-for "$channel"\n  observe\nfi\n# 提前或错误通知不能变成 PASS，也不再次等待/启动。\nif [ "$dead" != 1 ]; then exit 2; fi\nprintf \'%s\\n\' "$state" > "$record/observer-$observer.terminal"\ncase "$status" in 0|1|2) ;; *) exit 2;; esac\nprintf \'{"status":"HEAD2_P32_PREPARE_REAL_TERMINAL","pane":"%s","pane_pid":%s,"pane_exit":%s}\\n\' "$pane" "$driver_pid" "$status"\nexit "$status"\n'

assert observer.count('__ACTUAL_PANE_LINE__')==1
observer=observer.replace('__ACTUAL_PANE_LINE__',pane+' '+pid+' '+window)
with (boot/'observe_prepare_r14.sh').open('x') as f:f.write(observer)
code,stdout,stderr=command('same-pane-observer',['bash',str(boot/'observe_prepare_r14.sh')],(0,1,2))
print(stdout.decode(),end='',flush=True)
if stderr:print(json.dumps({'phase':'OBSERVER_STDERR','stderr':stderr.decode()},ensure_ascii=False),flush=True)
_,state,_=command('terminal-identity',['tmux','display-message','-p','-t',pane,'#{session_name}|#{window_id}|#{pane_id}|#{pane_dead}|#{pane_dead_status}|#{pane_pid}'],(0,))
parts=state.decode().strip().split('|');assert parts[:3]==[session,window,pane] and parts[3]=='1' and parts[4] in ['0','1','2'] and parts[5]==pid and int(parts[4])==code
command('reclaim-natural-dead-owned-pane',['tmux','kill-pane','-t',pane],(0,))
with (boot/'same-ssh.json').open('x') as f:json.dump(rows,f,ensure_ascii=False,indent=2);f.write('\n')
paths=sorted(path for directory in (phase,boot) if directory.exists() for path in directory.rglob('*') if path.is_file());assert all(not path.is_symlink() for path in paths)
archive=boot/'head2-p32-preparation-originals.tar.gz'
with tarfile.open(archive,'x:gz') as stream:
 for path in paths:stream.add(path,arcname=str(path.relative_to(base)),recursive=False)
raw=archive.read_bytes();result=phase/'prepare-result-r14.json';mismatch=phase/'identity-mismatch-r14.json'
result_ref=None if not result.exists() else {'path':str(result),'sha256':hashlib.sha256(result.read_bytes()).hexdigest(),'bytes':result.stat().st_size}
print(json.dumps({'phase':'HEAD2_P32_SOFTWARE_PREPARE_ARCHIVE_READY','sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'files':len(paths),'source_bytes':sum(path.stat().st_size for path in paths),'base64':base64.b64encode(raw).decode(),'runtime_pid':int(pid),'pane_exit':int(parts[4]),'prepare_result':result_ref,'identity_mismatch':None if not mismatch.exists() else json.loads(mismatch.read_text()),'uart_operations':0,'go_created':False,'field_created':False},ensure_ascii=False),flush=True)
raise SystemExit(code)

PYREMOTE
